/**
 * @file    ui_text.h
 * @brief   UI text identifiers (generated by tools/gen-ui-text.py).
 */
#ifndef UI_TEXT_H
#define UI_TEXT_H

typedef enum
{
    TXT_TAB_ALL,
    TXT_TAB_FAV,
    TXT_WAITING,
    TXT_WAITING_HINT,
    TXT_ACTIVE,
    TXT_PENDING,
    TXT_EMPTY,
    TXT_FAV_EMPTY,
    TXT_SELECT_FAILED,
    TXT_HOST_TIMEOUT,
    TXT_EDIT_FAILED,
    TXT_COUNT
} UiTextId;

/** The text in the current UI language. */
const char *ui_text(UiTextId id);

#endif /* UI_TEXT_H */
